// Pull recent Karakeep bookmarks, keep the last 7 days, build the prompt.
const res = $input.first().json;
const raw = Array.isArray(res.bookmarks) ? res.bookmarks : (Array.isArray(res) ? res : []);
const weekAgo = Date.now() - 7 * 24 * 3600 * 1000;
const items = raw.filter((b) => {
  const t = Date.parse(b.createdAt || b.created_at || '');
  return isNaN(t) ? true : t >= weekAgo;
});
const list = items.map((b, i) => {
  const c = b.content || {};
  const url = c.url || b.url || '';
  const title = b.title || c.title || url || 'untitled';
  const tags = (b.tags || []).map((t) => t.name || t).filter(Boolean).join(', ');
  return (i + 1) + '. ' + title + (tags ? '  [' + tags + ']' : '') + '\n   ' + url;
}).join('\n');

const sys = "You are the reader's research chief of staff. Their detailed profile is set in this node - replace this block for your own use.\nGiven the list of items the reader bookmarked this week, produce concise markdown with exactly these sections:\n## Top 5 reads   (ranked, one line each: what it is + why it matters to the reader's goals; pick from the list only)\n## 3 post angles (each: a specific title, a 2-bullet outline, which skill/asset it leverages; bias to weekend-sized)\n## Market signal (one hiring / comp / tech-shift observation worth acting on)\n## Weekend lab project (one <1 weekend project that would give interview-defensible depth)\nIf the list is empty, use the reader's standing themes and still produce all four sections.";
const user = items.length
  ? ('Bookmarks saved this week (' + items.length + '):\n\n' + list)
  : 'Nothing was bookmarked this week. Use the standing themes to still produce all four sections.';
return [{ json: { sysPrompt: sys, userMsg: user, count: items.length } }];
